// Reads who is signed in straight from supabase-js's stored session, without loading supabase-js.
// The header button is on every page, so it must stay tiny: it only needs a name for the initials.
// The stored session may be stale (an expired refresh token); the widgets that talk to the database
// validate it and clear it, and the button follows through the events below.
import { resolveSupabaseUrl } from '../common/runtime-config';

export interface PeekedUser {
  name: string;
  email: string;
}

/** supabase-js's default storage key: `sb-<first label of the project host>-auth-token`. */
export function sessionStorageKey(supabaseUrl: string = resolveSupabaseUrl()): string {
  return `sb-${new URL(supabaseUrl).hostname.split('.')[0]}-auth-token`;
}

export function peekUser(): PeekedUser | null {
  let raw: string | null;
  try {
    raw = localStorage.getItem(sessionStorageKey());
  } catch {
    return null; // storage blocked
  }
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    const user = parsed?.user ?? parsed?.currentSession?.user;
    if (!user?.id) return null;
    const email = typeof user.email === 'string' ? user.email : '';
    const metaName = user.user_metadata?.display_name;
    const name = typeof metaName === 'string' && metaName.trim() ? metaName.trim() : email.split('@')[0];
    return { name, email };
  } catch {
    return null;
  }
}

/** Up to two letters: first and last word of the name ("Imène R. Goumiri" → "IG"), else the first two letters. */
export function initials(name: string): string {
  const words = name.trim().split(/[\s._-]+/).filter(Boolean);
  if (!words.length) return '?';
  const first = [...words[0]][0] ?? '';
  const last = words.length > 1 ? ([...words[words.length - 1]][0] ?? '') : ([...words[0]][1] ?? '');
  return (first + last).toUpperCase();
}

/** Reaches window whenever this page signs in or out: fired by <rgai-auth> on sign-in (bubbling, composed) and by
 *  signOutAndClearSession on sign-out, whichever widget or dialog did it. Another tab is covered by `storage`. */
export const AUTH_CHANGED = 'rgai-auth-changed';
