// <rg-account-button>: the site-wide account control for the Squarespace header.
//   Signed out: an avatar placeholder; a click opens the sign-in / sign-up dialog.
//   Signed in:  a circle with the person's initials; a click opens a menu (name, settings, sign out).
// Attributes: account-href (default "/account"), the settings page.
import { escapeHtml } from '../common/sanitize';
import { initials, peekUser, sessionStorageKey, AUTH_CHANGED, type PeekedUser } from './session-peek';

const css = `
:host { display: inline-flex; position: relative; color: inherit; font-family: inherit; line-height: 1; }
*, *::before, *::after { box-sizing: border-box; }
/* Works on any page colour: a light pastel disc inside a black ring, with a black icon (signed out) or black
   initials (signed in). Each page of the site has its own colours, so nothing here follows the theme.
   The disc is four flat diagonal bands (light apricot, yellow, green, cyan). A 135° gradient runs corner to corner of
   the square box, but the circle only covers its middle 70.7% (14.64%–85.36%), so the stops are spread over
   that part: every band shows at the same width inside the circle. */
.trigger {
  --rg-account-bands: linear-gradient(135deg, #ffe8b3 0 32.32%, #fdffb6 32.32% 50%, #caffbf 50% 67.68%, #9bf6ff 67.68% 100%);
  width: var(--rg-account-size, 34px); height: var(--rg-account-size, 34px); border-radius: 999px; padding: 0; margin: 0;
  display: inline-flex; align-items: center; justify-content: center; cursor: pointer;
  border: none; background: #fff var(--rg-account-bands); color: #000; font: inherit; box-shadow: 0 0 0 1.5px #000, 0 0 0 3px rgba(255, 255, 255, .55);
  transition: background-color .15s ease, transform .1s ease;
}
.trigger:hover { background-image: linear-gradient(rgba(0, 0, 0, .08), rgba(0, 0, 0, .08)), var(--rg-account-bands); }
.trigger:active { transform: scale(.96); }
.trigger:focus-visible { outline: 2px solid #000; outline-offset: 4px; }
.trigger { overflow: hidden; }
.trigger svg.avatar { width: 100%; height: 100%; }
.trigger span { font-weight: 700; font-size: calc(var(--rg-account-size, 34px) * .4); letter-spacing: .02em; }
.menu {
  position: absolute; top: calc(100% + 10px); right: 0; z-index: 1000; min-width: 220px; max-width: 280px;
  background: #fff; color: #0f172a; border-radius: 12px; padding: .4rem;
  box-shadow: 0 12px 32px rgba(15, 23, 42, .22), 0 2px 6px rgba(15, 23, 42, .12);
  font: 15px/1.35 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; text-align: left;
}
.menu[hidden] { display: none; }
.who { padding: .55rem .7rem .65rem; border-bottom: 1px solid #e2e8f0; margin-bottom: .3rem; }
.who b { display: block; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.who small { display: block; color: #64748b; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.item {
  display: block; width: 100%; padding: .55rem .7rem; border: none; border-radius: 8px; background: none;
  color: inherit; font: inherit; text-align: left; text-decoration: none; cursor: pointer;
}
.item:hover, .item:focus-visible { background: #f1f5f9; outline: none; }
`;

// The usual "no profile photo" placeholder: a solid bust cut off by the bottom of the disc (the trigger clips it).
const personIcon = `<svg class="avatar" viewBox="0 0 34 34" fill="currentColor" aria-hidden="true"><circle cx="17" cy="13" r="6"/><path d="M4 34c0-7.5 5.8-12.5 13-12.5S30 26.5 30 34z"/></svg>`;

export class RgAccountButton extends HTMLElement {
  private root: ShadowRoot;
  private user: PeekedUser | null = null;
  private menuOpen = false;
  private readonly refresh = () => this.update();
  private readonly onStorage = (e: StorageEvent) => {
    if (e.key === null || e.key === sessionStorageKey()) this.update();
  };
  private readonly onOutside = (e: Event) => {
    if (this.menuOpen && !e.composedPath().includes(this)) this.setMenu(false);
  };
  private readonly onKey = (e: KeyboardEvent) => {
    if (e.key === 'Escape' && this.menuOpen) {
      this.setMenu(false);
      this.root.querySelector<HTMLButtonElement>('.trigger')?.focus();
    }
  };

  constructor() {
    super();
    this.root = this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    window.addEventListener(AUTH_CHANGED, this.refresh);
    window.addEventListener('storage', this.onStorage);
    document.addEventListener('click', this.onOutside, true);
    document.addEventListener('keydown', this.onKey);
    this.update();
  }

  disconnectedCallback() {
    window.removeEventListener(AUTH_CHANGED, this.refresh);
    window.removeEventListener('storage', this.onStorage);
    document.removeEventListener('click', this.onOutside, true);
    document.removeEventListener('keydown', this.onKey);
  }

  private update() {
    this.user = peekUser();
    this.menuOpen = false;
    this.render();
  }

  private setMenu(open: boolean) {
    this.menuOpen = open;
    const menu = this.root.querySelector<HTMLElement>('.menu');
    const trigger = this.root.querySelector<HTMLElement>('.trigger');
    if (menu) menu.hidden = !open;
    trigger?.setAttribute('aria-expanded', String(open));
    if (open) this.root.querySelector<HTMLElement>('.item')?.focus();
  }

  private render() {
    const u = this.user;
    const href = this.getAttribute('account-href') || '/account';
    this.root.innerHTML = u
      ? `<style>${css}</style>
         <button type="button" class="trigger" aria-haspopup="menu" aria-expanded="false" aria-label="Account menu for ${escapeHtml(u.name)}" title="${escapeHtml(u.name)}"><span>${escapeHtml(initials(u.name))}</span></button>
         <div class="menu" role="menu" hidden>
           <div class="who"><b>${escapeHtml(u.name)}</b>${u.email ? `<small>${escapeHtml(u.email)}</small>` : ''}</div>
           <a class="item" role="menuitem" href="${escapeHtml(href)}">Account settings</a>
           <button type="button" class="item" role="menuitem" data-action="sign-out">Sign out</button>
         </div>`
      : `<style>${css}</style>
         <button type="button" class="trigger" aria-haspopup="dialog" aria-label="Sign in or create an account" title="Sign in">${personIcon}</button>`;

    this.root.querySelector('.trigger')!.addEventListener('click', async () => {
      if (this.user) {
        this.setMenu(!this.menuOpen);
      } else {
        const { openAuthDialog } = await import('./account-dialog');
        openAuthDialog();
      }
    });
    this.root.querySelector('[data-action="sign-out"]')?.addEventListener('click', async () => {
      this.setMenu(false);
      const { signOut } = await import('./account-dialog');
      await signOut();
    });
  }
}

if (!customElements.get('rg-account-button')) {
  customElements.define('rg-account-button', RgAccountButton);
}
